#include <bits/stdc++.h>
using namespace std;

static int n, t;

struct Room {
    int i, j;
    array<bool, 61> infected;
    array<bool, 61> accessible;
    int scientists, capsules;

    Room() : scientists(0), capsules(0) {
        infected.fill(false);
        accessible.fill(true);
    }

    int get_node_id(int timestamp) const {
        return 2 + i + n * j + (n * n) * timestamp;
    }

    void set_reactor() {
        accessible.fill(false);
    }

    void set_infected(int timestamp = 0) {
        if (accessible[timestamp]) {
            accessible[timestamp] = false;
            infected[timestamp] = true;
        }
    }

    void spread_infection(int timestamp);
};

static array<array<Room, 10>, 10> floorplan;

void Room::spread_infection(int timestamp) {
    if (!infected[timestamp]) return;

    set_infected(timestamp + 1);

    if (i > 0) floorplan[i - 1][j].set_infected(timestamp + 1);
    if (i < n - 1) floorplan[i + 1][j].set_infected(timestamp + 1);
    if (j > 0) floorplan[i][j - 1].set_infected(timestamp + 1);
    if (j < n - 1) floorplan[i][j + 1].set_infected(timestamp + 1);
}

struct PushRelabel {
    struct Edge {
        int to, rev, cap;
    };

    int N, s, t;
    vector<vector<Edge>> g;
    vector<int> height, excess, current;
    vector<char> in_queue;
    queue<int> active;

    PushRelabel(int n) : N(n), g(n), height(n), excess(n), current(n),
                         in_queue(n, false) {}

    void add_edge(int v, int to, int cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{v, (int)g[v].size(), 0};
        g[v].push_back(a);
        g[to].push_back(b);
    }

    void enqueue(int v) {
        if (v != s && v != t && excess[v] > 0 && !in_queue[v]) {
            in_queue[v] = true;
            active.push(v);
        }
    }

    void push(int u, Edge &e) {
        int d = min(excess[u], e.cap);
        if (d == 0) return;

        e.cap -= d;
        g[e.to][e.rev].cap += d;
        excess[u] -= d;
        excess[e.to] += d;

        enqueue(e.to);
    }

    void relabel(int u) {
        int min_height = 2 * N;

        for (const Edge &e : g[u]) {
            if (e.cap > 0) {
                min_height = min(min_height, height[e.to]);
            }
        }

        height[u] = min_height + 1;
    }

    void discharge(int u) {
        while (excess[u] > 0) {
            if (current[u] == (int)g[u].size()) {
                relabel(u);
                current[u] = 0;
            } else {
                Edge &e = g[u][current[u]];

                if (e.cap > 0 && height[u] == height[e.to] + 1) {
                    push(u, e);
                } else {
                    current[u]++;
                }
            }
        }
    }

    int max_flow(int source, int sink) {
        s = source;
        t = sink;

        const int INF = 1000000000;

        height[s] = N;
        excess[s] = INF;

        for (Edge &e : g[s]) {
            if (e.cap > 0) {
                int d = e.cap;
                e.cap = 0;
                g[e.to][e.rev].cap += d;
                excess[s] -= d;
                excess[e.to] += d;
                enqueue(e.to);
            }
        }

        while (!active.empty()) {
            int u = active.front();
            active.pop();
            in_queue[u] = false;
            discharge(u);
        }

        return excess[t];
    }
};

int main() {
    ios::sync_with_stdio(false);

    cin >> n >> t;

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            floorplan[i][j].i = i;
            floorplan[i][j].j = j;

            if (line[j] == 'Y') floorplan[i][j].set_reactor();
            else if (line[j] == 'Z') floorplan[i][j].set_infected();
            else floorplan[i][j].scientists = line[j] - '0';
        }
    }

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                floorplan[i][j].capsules = line[j] - '0';
            }
        }
    }

    for (int c = 0; c <= t; c++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (c < t) floorplan[i][j].spread_infection(c);
            }
        }
    }

    PushRelabel mf(n * n * (t + 1) + 2);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            const Room &room = floorplan[i][j];

            if (room.scientists > 0) {
                mf.add_edge(0, room.get_node_id(0), room.scientists);
            }

            if (room.capsules > 0) {
                mf.add_edge(room.get_node_id(t), 1, room.capsules);
            }

            for (int c = 0; c < t; c++) {
                if (room.capsules > 0) {
                    mf.add_edge(room.get_node_id(c), room.get_node_id(t), 1000);
                }

                if (room.accessible[c]) {
                    if (i > 0 && floorplan[i - 1][j].accessible[c]) {
                        mf.add_edge(room.get_node_id(c),
                                    floorplan[i - 1][j].get_node_id(c + 1), 1000);
                    }

                    if (i < n - 1 && floorplan[i + 1][j].accessible[c]) {
                        mf.add_edge(room.get_node_id(c),
                                    floorplan[i + 1][j].get_node_id(c + 1), 1000);
                    }

                    if (j > 0 && floorplan[i][j - 1].accessible[c]) {
                        mf.add_edge(room.get_node_id(c),
                                    floorplan[i][j - 1].get_node_id(c + 1), 1000);
                    }

                    if (j < n - 1 && floorplan[i][j + 1].accessible[c]) {
                        mf.add_edge(room.get_node_id(c),
                                    floorplan[i][j + 1].get_node_id(c + 1), 1000);
                    }
                }
            }
        }
    }

    cout << mf.max_flow(0, 1) << '\n';

    return 0;
}
